<template><strategy-dialog title="Couverture des types" @close="$emit('close')"><div class="coverage-summary"><div class="coverage-score" :style="{'--score':analysis.score+'%','--score-color':analysis.score>=75?'#6aab90':analysis.score>=50?'#b4a16e':'#bd7a82'}" :aria-label="analysis.score+' sur 100'"><span><strong>{{ analysis.score }}</strong><small>/ 100</small></span></div><div><h3>Les réponses de ton équipe</h3><p>Une mesure de ta couverture des types, indépendante des niveaux et de la puissance brute.</p><small>Offensive {{ analysis.offenseScore }} / 100 · Défensive {{ analysis.defenseScore }} / 100</small></div></div>
 <div class="coverage-team" aria-label="Équipe analysée"><div v-for="(p,i) in team" :key="p.uuid||i"><pokemon-portrait :src="$pokemonSprite(p)" :alt="p.name"/><small>{{ p.name }}</small></div></div>
