</strategy-dialog></template>
<script>
import StrategyDialog from './StrategyDialog.vue';import CoverageGrid from './CoverageGrid.vue';import PokemonPortrait from '../PokemonPortrait.vue';import{analyzeTeam}from'@/services/teamCoverage';
export default{components:{StrategyDialog,CoverageGrid,PokemonPortrait},props:{team:Array},data:()=>({defensive:false}),computed:{analysis(){return analyzeTeam(this.team);}}};
</script>
<style scoped>.coverage-summary{display:flex;align-items:center;gap:22px;margin-bottom:16px}.coverage-summary h3{font:22px Georgia,serif;margin:0 0 8px;color:var(--journal-heading)}.coverage-summary p{font-size:12px;line-height:1.6;color:var(--journal-muted);margin:0 0 8px}.coverage-summary small{font-size:10px;color:var(--journal-muted)}.coverage-score{flex:none;width:104px;height:104px;border-radius:50%;background:conic-gradient(var(--score-color) var(--score),var(--journal-border) 0);display:grid;place-items:center}.coverage-score>span{width:88px;height:88px;border-radius:50%;background:var(--journal-paper);display:flex;align-items:center;justify-content:center;flex-direction:column}.coverage-score strong{font:700 34px Georgia,serif;color:var(--journal-heading)}.coverage-team{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:9px;margin:14px 0 18px}.coverage-team>div{min-width:0;text-align:center;padding:7px;border:1px solid var(--journal-border);border-radius:9px;background:var(--journal-card)}.coverage-team .pokemon-portrait{height:48px;width:48px;margin:auto;image-rendering:pixelated}.coverage-team small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:10px;margin-top:3px}.coverage-tabs{display:flex;gap:8px;border-bottom:1px solid var(--journal-border);padding-bottom:12px;margin-bottom:16px}.coverage-tabs button{flex:1;min-height:42px;border:1px solid var(--journal-border);border-radius:8px;background:var(--journal-card);color:var(--journal-ink);font:600 12px var(--journal-font);cursor:pointer}.coverage-tabs [aria-pressed=true]{background:var(--journal-selected);border-color:var(--journal-accent)}.score-explanation{margin-top:17px;font-size:11px;line-height:1.6;color:var(--journal-muted)}summary{cursor:pointer;font-weight:600;min-height:32px}@media(max-width:650px){.coverage-summary{gap:13px}.coverage-summary h3{font-size:18px}.coverage-summary p{font-size:11px}.coverage-score{width:82px;height:82px}.coverage-score>